<body>

<div class="page-header">
  <h1>No Perfect Car: Seven-Dimension Trade-Off Analysis</h1>
  <p>Every model excels somewhere and concedes elsewhere. Parallel coordinates show the full shape of each car's strengths and weaknesses across price, efficiency, power, safety, space, resale value, and emissions.</p>
</div>

<div class="chart-wrap">
  <div class="legend">
    <div class="legend-item">
      <div class="legend-swatch" style="background:var(--suv);"></div>
      SUV <span class="legend-count">(9 models)</span>
    </div>
    <div class="legend-item">
      <div class="legend-swatch" style="background:var(--sedan);"></div>
      Sedan <span class="legend-count">(8 models)</span>
    </div>
    <div class="legend-item">
      <div class="legend-swatch" style="background:var(--electric);"></div>
      Electric <span class="legend-count">(8 models)</span>
    </div>
    <div class="legend-item" style="margin-left:auto;">
      <div class="legend-swatch" style="background:var(--highlight); height:2.5px;"></div>
      <span style="font-size:0.78rem;color:var(--text-dim);">★ Top performer on axis</span>
    </div>
  </div>

  <svg id="chart" viewBox="0 0 1040 560" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <marker id="arr" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto">
        <path d="M0,0 L6,3 L0,6 Z" fill="#b8a890"/>
      </marker>
    </defs>
    <!-- generated by JS below -->
  </svg>

  <div class="section-note">
    <strong>Reading the chart:</strong> Each line traces one car across all seven axes. Lines that cross between adjacent axes signal a trade-off — most visible between <strong>Power ↔ Fuel Efficiency</strong> (high performance cars drop in efficiency) and between <strong>Price ↔ Resale Value</strong> (luxury models are expensive but don't always hold value best). Electric vehicles form a distinctive flat plateau at the top of Emissions, while SUVs cluster high on Interior Space but low on Fuel Efficiency.
  </div>
</div>

<script>
// ─── DATA ────────────────────────────────────────────────────────────────────
const cars = [
  {model:"Toyota RAV4",     type:"SUV",      vals:[72,55,58,82,78,88,52]},
  {model:"Honda CR-V",      type:"SUV",      vals:[68,58,55,85,80,82,50]},
  {model:"Ford Explorer",   type:"SUV",      vals:[45,38,82,78,90,62,35]},
  {model:"Chevy Tahoe",     type:"SUV",      vals:[30,28,90,75,95,70,25]},
  {model:"Jeep Wrangler",   type:"SUV",      vals:[50,35,72,60,65,92,30]},
  {model:"Hyundai Tucson",  type:"SUV",      vals:[78,60,50,80,72,68,55]},
  {model:"Mazda CX-5",      type:"SUV",      vals:[70,56,62,88,68,75,48]},
  {model:"Subaru Outback",  type:"SUV",      vals:[65,52,55,92,74,72,45]},
  {model:"BMW X5",          type:"SUV",      vals:[22,40,88,90,82,58,38]},
  {model:"Toyota Camry",    type:"Sedan",    vals:[82,78,48,84,55,85,68]},
  {model:"Honda Accord",    type:"Sedan",    vals:[75,75,55,88,58,80,65]},
  {model:"Mazda 3",         type:"Sedan",    vals:[80,72,52,82,45,70,62]},
  {model:"BMW 3 Series",    type:"Sedan",    vals:[35,55,78,86,48,60,50]},
  {model:"Mercedes C-Class",type:"Sedan",    vals:[30,50,80,88,50,55,48]},
  {model:"Hyundai Sonata",  type:"Sedan",    vals:[85,70,45,78,60,58,60]},
  {model:"Kia K5",          type:"Sedan",    vals:[88,68,50,76,58,55,58]},
  {model:"Subaru Legacy",   type:"Sedan",    vals:[74,62,52,90,55,62,55]},
  {model:"Tesla Model 3",   type:"Electric", vals:[55,92,85,90,48,65,98]},
  {model:"Tesla Model Y",   type:"Electric", vals:[48,88,82,92,72,68,98]},
  {model:"Chevy Bolt EV",   type:"Electric", vals:[78,95,42,72,45,40,98]},
  {model:"Nissan Leaf",     type:"Electric", vals:[82,90,35,70,42,35,98]},
  {model:"Ford Mustang Mach-E",type:"Electric",vals:[42,85,78,85,65,55,98]},
  {model:"Hyundai Ioniq 5", type:"Electric", vals:[52,88,72,88,75,62,98]},
  {model:"BMW iX",          type:"Electric", vals:[18,82,90,92,78,48,98]},
  {model:"Rivian R1S",      type:"Electric", vals:[20,72,95,80,88,45,98]},
];

const dims = [
  {key:"price_score",    label:"Price",        sub:"(Affordability)"},
  {key:"fuel_efficiency",label:"Fuel Eff.",    sub:"(Economy)"},
  {key:"power",          label:"Power",        sub:"(Performance)"},
  {key:"safety",         label:"Safety",       sub:"(Crash Rating)"},
  {key:"interior_space", label:"Interior",     sub:"(Space)"},
  {key:"resale_value",   label:"Resale",       sub:"(Value)"},
  {key:"emission_rating",label:"Emissions",    sub:"(Cleanliness)"},
];

const colors = { SUV:"#c2410c", Sedan:"#1e6ba8", Electric:"#0f7b5a" };
const dimAlpha = { SUV:0.60, Sedan:0.60, Electric:0.60 };

// ─── LAYOUT ──────────────────────────────────────────────────────────────────
const svgEl = document.getElementById("chart");
const W = 1040, H = 560;
const padL = 52, padR = 52, padT = 90, padB = 56;
const nDims = dims.length;
const axisXs = dims.map((_, i) => padL + i * (W - padL - padR) / (nDims - 1));
const axisTop = padT, axisBot = H - padB;
const axisH = axisBot - axisTop;

function yScale(val) { return axisBot - (val / 100) * axisH; }

// find top performer per axis
const topPerAxis = dims.map((d, di) => {
  let best = -1, bestCar = null;
  cars.forEach(c => { if(c.vals[di] > best){ best = c.vals[di]; bestCar = c; }});
  return { car: bestCar, val: best };
});

// ─── DRAW ─────────────────────────────────────────────────────────────────────
function svgEl2(tag, attrs, children) {
  const el = document.createElementNS("http://www.w3.org/2000/svg", tag);
  Object.entries(attrs).forEach(([k,v]) => el.setAttribute(k, v));
  if (children) {
    if (typeof children === "string") el.textContent = children;
    else children.forEach(c => el.appendChild(c));
  }
  return el;
}

function mk(tag, attrs, text) {
  const el = document.createElementNS("http://www.w3.org/2000/svg", tag);
  Object.entries(attrs).forEach(([k,v]) => el.setAttribute(k, v));
  if (text !== undefined) el.textContent = text;
  return el;
}

const svg = document.querySelector("svg#chart");

// Subtle background bands between alternating axis pairs
for(let i=0;i<nDims-1;i++){
  if(i%2===0){
    const band = mk("rect",{
      x:axisXs[i], y:axisTop-8,
      width:axisXs[i+1]-axisXs[i],
      height:axisH+16,
      fill:"rgba(0,0,0,0.025)", rx:"0"
    });
    svg.appendChild(band);
  }
}

// Grid lines at 25, 50, 75
[25,50,75].forEach(v => {
  const y = yScale(v);
  const gl = mk("line",{x1:axisXs[0],y1:y,x2:axisXs[nDims-1],y2:y,stroke:"rgba(0,0,0,0.07)","stroke-width":"1","stroke-dasharray":"3,4"});
  svg.appendChild(gl);
  const gt = mk("text",{"x":axisXs[0]-8,"y":y+3.5,"text-anchor":"end","font-family":"IBM Plex Mono,monospace","font-size":"8.5","fill":"rgba(0,0,0,0.3)"}, String(v));
  svg.appendChild(gt);
});

// ─── POLYLINES ────────────────────────────────────────────────────────────────
// Draw non-highlighted (background) lines first
["SUV","Sedan","Electric"].forEach(type => {
  const group = mk("g",{opacity:"1"});
  svg.appendChild(group);
  cars.filter(c=>c.type===type).forEach(car => {
    const pts = car.vals.map((v,di) => `${axisXs[di]},${yScale(v)}`).join(" ");
    const line = mk("polyline",{
      points: pts,
      fill:"none",
      stroke: colors[type],
      "stroke-width":"1.4",
      "stroke-opacity":"0.40",
      "stroke-linecap":"round",
      "stroke-linejoin":"round",
    });
    // tooltip
    const title = mk("title",{});
    title.textContent = `${car.model} (${type})\n` + dims.map((d,di)=>`${d.label}: ${car.vals[di]}`).join("\n");
    line.appendChild(title);
    group.appendChild(line);
  });
});

// ─── HIGHLIGHT TOP PERFORMERS ─────────────────────────────────────────────────
topPerAxis.forEach((tp, di) => {
  const car = tp.car;
  const pts = car.vals.map((v,dj) => `${axisXs[dj]},${yScale(v)}`).join(" ");
  // If not already drawn with highlight
  const hl = mk("polyline",{
    points: pts,
    fill:"none",
    stroke: colors[car.type],
    "stroke-width":"2.6",
    "stroke-opacity":"0.72",
    "stroke-linecap":"round",
    "stroke-linejoin":"round",
  });
  const title2 = mk("title",{});
  title2.textContent = `${car.model} — top on ${dims[di].label}\n` + dims.map((d,dj)=>`${d.label}: ${car.vals[dj]}`).join("\n");
  hl.appendChild(title2);
  svg.appendChild(hl);
});

// ─── AXES ─────────────────────────────────────────────────────────────────────
dims.forEach((dim, di) => {
  const x = axisXs[di];

  // Axis line
  svg.appendChild(mk("line",{x1:x,y1:axisTop,x2:x,y2:axisBot,stroke:"#4a4540","stroke-width":"1.5"}));

  // Tick marks & labels at 0, 25, 50, 75, 100
  [0,25,50,75,100].forEach(v => {
    const y = yScale(v);
    svg.appendChild(mk("line",{x1:x-4,y1:y,x2:x+4,y2:y,stroke:"#4a4540","stroke-width":"1"}));
    if(v===0||v===100){
      const tl = mk("text",{"x":x+7,"y":y+3.5,"class":"axis-tick"}, String(v));
      if(di===nDims-1) tl.setAttribute("text-anchor","end"), tl.setAttribute("x",x-7);
      svg.appendChild(tl);
    }
  });

  // Axis label
  const lbl = mk("text",{"x":x,"y":axisTop-26,"class":"axis-label","text-anchor":"middle"}, dim.label);
  svg.appendChild(lbl);
  const sublbl = mk("text",{"x":x,"y":axisTop-13,"class":"axis-sublabel","text-anchor":"middle"}, dim.sub);
  svg.appendChild(sublbl);

  // Top performer badge
  const tp = topPerAxis[di];
  const ty = yScale(tp.val);
  // Gold circle
  svg.appendChild(mk("circle",{cx:x,cy:ty,r:"5.5",fill:"#d4a73a","stroke":"#ffffff","stroke-width":"1.5"}));
  // Short name label
  const shortName = tp.car.model.split(" ").slice(-1)[0];
  const badgeX = (di < nDims-1) ? x+9 : x-9;
  const badgeAnchor = (di < nDims-1) ? "start" : "end";
  const badge = mk("text",{
    x: badgeX, y: ty-7,
    "class":"top-badge",
    "text-anchor": badgeAnchor,
    fill: colors[tp.car.type]
  }, tp.car.model);
  svg.appendChild(badge);
});

// ─── TRADE-OFF ANNOTATION ─────────────────────────────────────────────────────
// Arrow annotation between Power and Fuel Efficiency axes
const x1 = axisXs[1], x2 = axisXs[2];
const midX = (x1+x2)/2, midY = axisTop + axisH*0.35;
const ann = mk("text",{x:midX,y:midY-10,"class":"callout-line","text-anchor":"middle"}, "⟷ Power/Efficiency trade-off");
svg.appendChild(ann);
const ann2 = mk("text",{x:midX,y:midY+4,"class":"callout-line","text-anchor":"middle"}, "(heavy line crossings)");
svg.appendChild(ann2);

// Annotation for price/resale
const xp = axisXs[0], xr = axisXs[5];
const midX2 = (xp+xr)/2 + 10, midY2 = axisBot + 36;
// small note under axes
const ann3 = mk("text",{x:(axisXs[0]+axisXs[5])/2,y:H-8,"class":"callout-line","text-anchor":"middle","font-size":"10"}, "Price ↔ Resale: luxury brands are costly but don't always retain value best");
svg.appendChild(ann3);

// Electric emissions flat-line annotation
const xE = axisXs[6];
const eY = yScale(98);
const eAnn = mk("text",{x:xE+14,y:eY+1,"class":"callout-line","text-anchor":"start","font-size":"10","fill":"#0f7b5a"}, "← All EVs score 98");
svg.appendChild(eAnn);

// SUV space cluster annotation
const xS = axisXs[4];
svg.appendChild(mk("text",{x:xS+10,y:yScale(85),"class":"callout-line","text-anchor":"start","font-size":"10","fill":"#c2410c"}, "← SUVs cluster high"));
svg.appendChild(mk("text",{x:xS+10,y:yScale(85)+12,"class":"callout-line","text-anchor":"start","font-size":"10","fill":"#c2410c"}, "   on space"));

</script>
</body>
